Validation XML d'un fichier ADMX avant déploiement<pre><code># Validate ADMX XML syntax before deploying to Central Store
param(
    [Parameter(Mandatory = $true)]
    [string]$AdmxPath
)

if (-not (Test-Path $AdmxPath)) {
    Write-Error "File not found: $AdmxPath"
    exit 1
}

$errors = [System.Collections.Generic.List[string]]::new()

try {
    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.ValidationType = [System.Xml.ValidationType]::None
    $settings.IgnoreComments = $true

    $reader = [System.Xml.XmlReader]::Create($AdmxPath, $settings)
    $xml    = New-Object System.Xml.XmlDocument
    $xml.Load($reader)
    $reader.Close()

    # Check mandatory namespace
    $ns = $xml.policyDefinitions.policyNamespaces.target.namespace
    if ([string]::IsNullOrEmpty($ns)) {
        $errors.Add("Missing or empty namespace in &lt;policyNamespaces&gt;&lt;target&gt;")
    }

    # Check that all $(string.X) references exist in at least one ADML
    $admxDir   = Split-Path $AdmxPath
    $admlFiles = Get-ChildItem -Path $admxDir -Filter "*.adml" -Recurse
    $allStrings = @{}
    foreach ($adml in $admlFiles) {
        try {
            $admlXml = [xml](Get-Content $adml.FullName -Encoding UTF8)
            foreach ($str in $admlXml.policyDefinitionResources.resources.stringTable.string) {
                $allStrings[$str.id] = $true
            }
        } catch {
            $errors.Add("ADML parse error in $($adml.Name): $_")
        }
    }

    $admxContent = Get-Content $AdmxPath -Raw
    $refs        = [regex]::Matches($admxContent, '\$\(string\.(\w+)\)')
    foreach ($ref in $refs) {
        $id = $ref.Groups[1].Value
        if (-not $allStrings.ContainsKey($id)) {
            $errors.Add("String reference not found in any ADML: `$(string.$id)`")
        }
    }

} catch {
    $errors.Add("XML parse error: $_")
}

if ($errors.Count -eq 0) {
    Write-Host "ADMX validation passed: $AdmxPath"
} else {
    Write-Warning "ADMX validation failed: $AdmxPath"
    $errors | ForEach-Object { Write-Warning "  - $_" }
    exit 1
}
</code></pre> <pre><code>ADMX validation passed: C:\Temp\MonApp-ADMX\monapp.admx
</code></pre>

Validation de tous les ADMX du Central Store<pre><code># Batch validate all ADMX files in the Central Store
$domain       = $env:USERDNSDOMAIN
$centralStore = "\\$domain\SYSVOL\$domain\Policies\PolicyDefinitions"
$failed       = 0

Get-ChildItem -Path $centralStore -Filter "*.admx" | ForEach-Object {
    $file = $_
    try {
        $xml = [xml](Get-Content $file.FullName -Encoding UTF8)
        # Quick check: root element must be policyDefinitions
        if ($xml.policyDefinitions -eq $null) {
            Write-Warning "Invalid root element in: $($file.Name)"
            $failed++
        }
    } catch {
        Write-Warning "XML parse error in $($file.Name): $_"
        $failed++
    }
}

if ($failed -eq 0) {
    Write-Host "All ADMX files in Central Store are valid."
} else {
    Write-Warning "$failed file(s) failed validation. Check Event ID 4017 in Application log."
}
</code></pre> <p>En résumé</p> <p>L'Event ID 4017 signale un fichier ADMX non parsable dans le Central Store. GPMC ignore silencieusement le fichier défaillant. Validez la syntaxe XML et les références aux chaînes ADML avant tout déploiement. Un ADMX invalide en production passe inaperçu jusqu'à ce qu'un admin remarque des paramètres manquants.</p>

Audit WSUS — lecture directe des registry.pol du domaine<pre><code># Audit WSUS configuration deployed via GPO by reading registry.pol directly
# No need for RSoP or gpresult — reads the source of truth in SYSVOL

param(
    [string]$Domain       = $env:USERDNSDOMAIN,
    [string]$WsusKeyPath  = 'SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
)

$policiesRoot = "\\$Domain\SYSVOL\$Domain\Policies"
$wsusValues   = @('WUServer', 'WUStatusServer', 'UseWUServer', 'AUOptions', 'ScheduledInstallDay')

# Enumerate all GPOs
Get-GPO -All -Domain $Domain | ForEach-Object {
    $gpo  = $_
    $guid = $gpo.Id.ToString('B').ToUpper()
    $polPath = "$policiesRoot\$guid\Machine\Registry.pol"

    if (-not (Test-Path $polPath)) { return }

    # Parse and filter on WindowsUpdate key
    $records = Read-RegistryPol -Path $polPath |
        Where-Object { $_.KeyPath -like "$WsusKeyPath*" }

    if (-not $records) { return }

    Write-Host "`n=== GPO: $($gpo.DisplayName) ===" -ForegroundColor Cyan

    $records | ForEach-Object {
        $display = if ($_.Value -is [byte[]]) {
            "0x" + ($_.Value | ForEach-Object { $_.ToString('X2') }) -join ''
        } else { $_.Value }

        [PSCustomObject]@{
            Key       = $_.KeyPath -replace [regex]::Escape($WsusKeyPath), '...'
            ValueName = $_.ValueName
            Type      = $_.TypeName
            Value     = $display
        }
    } | Format-Table -AutoSize
}
</code></pre> Résultat attendu<pre><code>=== GPO: WSUS - Production ===

