Verify-LAPSAccess-E2E.ps1<pre><code># End-to-end verification: attempt to read LAPS password as a helpdesk user
# Run this script as a member of the helpdesk group (not as Domain Admin)
param(
    [Parameter(Mandatory)]
    [string]$TestComputerName
)

Write-Host "Testing LAPS access for computer: $TestComputerName" -ForegroundColor Cyan
Write-Host "Running as: $([System.Security.Principal.WindowsIdentity]::GetCurrent().Name)"
Write-Host ""

# Test LAPS v1
try {
    Import-Module AdmPwd.PS -ErrorAction Stop
    $v1 = Get-AdmPwdPassword -ComputerName $TestComputerName -ErrorAction Stop
    Write-Host "LAPS v1 read: OK — Password expires $($v1.ExpirationTimestamp)" -ForegroundColor Green
} catch {
    Write-Host "LAPS v1 read: FAILED — $_" -ForegroundColor Red
}

# Test LAPS v2
try {
    $v2 = Get-LapsADPassword -Identity $TestComputerName -AsPlainText -ErrorAction Stop
    Write-Host "LAPS v2 read: OK — Password expires $($v2.ExpirationTimestamp)" -ForegroundColor Green
} catch {
    Write-Host "LAPS v2 read: FAILED — $_" -ForegroundColor Red
}
</code></pre> <p>Production — Testez avec un compte helpdesk, pas Domain Admin</p> <p>Le test de lecture LAPS doit être réalisé avec un compte membre du groupe helpdesk, pas avec un compte Domain Admin. Un Domain Admin peut toujours lire <code>ms-Mcs-AdmPwd</code> via les droits implicites — ce test ne valide pas que le groupe opérationnel a bien accès.</p> <p>En résumé</p> <ul> <li>Déployer LAPS sans ACL helpdesk = mots de passe générés mais inexploitables en production</li> <li>Détection : audit des ACL sur l'OU avec <code>Get-Acl -Path "AD:\&lt;OU&gt;"</code></li> <li>Remédiation v1 : <code>Set-AdmPwdReadPasswordPermission</code> — remédiation v2 : <code>Set-LapsADReadPasswordPermission</code></li> <li>Validation : test de lecture avec un compte du groupe helpdesk, pas Domain Admin</li> <li>À faire avant la mise en production de LAPS, pas après le premier incident</li> </ul>

Détecter DisableMDMEnrollment sur le parc<pre><code># Run from management workstation — scans all Windows 10/11 machines
# Requires WinRM access to target machines

$computers = Get-ADComputer -Filter {
    OperatingSystem -like "Windows 10*" -or OperatingSystem -like "Windows 11*"
} -Properties LastLogonDate |
    Where-Object { $_.LastLogonDate -gt (Get-Date).AddDays(-30) }

$mdmKey    = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\MDM"
$valueName = "DisableMDMEnrollment"

$results = foreach ($computer in $computers) {
    $session = New-PSSession -ComputerName $computer.Name -ErrorAction SilentlyContinue
    if ($session) {
        $status = Invoke-Command -Session $session -ScriptBlock {
            param($key, $val)
            $v = Get-ItemProperty -Path $key -Name $val -ErrorAction SilentlyContinue
            [PSCustomObject]@{
                KeyExists   = (Test-Path $key)
                ValueExists = ($null -ne $v)
                Value       = if ($v) { $v.$val } else { "NOT SET" }
                Blocked     = ($v -and $v.$val -eq 1)
            }
        } -ArgumentList $mdmKey, $valueName
        Remove-PSSession $session

        [PSCustomObject]@{
            Computer    = $computer.Name
            OS          = $computer.OperatingSystem
            KeyPresent  = $status.KeyExists
            ValueSet    = $status.ValueExists
            CurrentValue = $status.Value
            MDMBlocked  = $status.Blocked
        }
    } else {
