Deploy-GpoStagingRing.ps1<pre><code># Deploy a GPO link to the staging ring OU only
# Staging ring = a representative sample OU (10% of fleet, mixed models)
# After 24h monitoring, a human approves promotion to production

param(
    [Parameter(Mandatory)]
    [string]$GpoName,

    [string]$StagingOu    = "OU=Staging-Ring,OU=Computers,DC=domain,DC=local",
    [string]$ProductionOu = "OU=Computers,DC=domain,DC=local",

    [ValidateSet("Staging", "Production")]
    [string]$Target = "Staging"
)

switch ($Target) {
    "Staging" {
        Write-Host "Linking '$GpoName' to staging ring: $StagingOu"
        New-GPLink -Name $GpoName -Target $StagingOu -LinkEnabled Yes -ErrorAction Stop
        Write-Host "Staging link created. Monitor for 24h before promoting to production."
    }

    "Production" {
        Write-Host "Promoting '$GpoName' to production: $ProductionOu"

        # Verify staging link still exists and GPO is unchanged
        $stagingLink = Get-GPInheritance -Target $StagingOu |
            Select-Object -ExpandProperty GpoLinks |
            Where-Object { $_.DisplayName -eq $GpoName }

        if (-not $stagingLink) {
            Write-Error "Staging link not found — cannot promote without completed staging"
            exit 1
        }

        New-GPLink -Name $GpoName -Target $ProductionOu -LinkEnabled Yes -ErrorAction Stop
        Write-Host "Production link created."
    }
}
</code></pre>

Audit-SYSVOLPermissions.ps1<pre><code># Audit NTFS permissions on SYSVOL GPO folders and flag unexpected write access
$domain     = $env:USERDNSDOMAIN
$sysvolBase = "\\$domain\SYSVOL\$domain\Policies"

# Identities that are allowed write access
$allowedWriters = @(
    "NT AUTHORITY\SYSTEM",
    "BUILTIN\Administrators",
    "CONTOSO\Domain Admins",
    "CONTOSO\Enterprise Admins"
)

$report = Get-GPO -All | ForEach-Object {
    $gpo     = $_
    $gpoPath = "$sysvolBase\{$($gpo.Id)}"

    if (-not (Test-Path $gpoPath)) {
        Write-Warning "SYSVOL folder missing for GPO: $($gpo.DisplayName) [{$($gpo.Id)}]"
        return
    }

    $acl = Get-Acl -Path $gpoPath
    foreach ($ace in $acl.Access) {
        $isWrite = $ace.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::Write
        if ($isWrite -and $ace.IdentityReference.Value -notin $allowedWriters) {
            [PSCustomObject]@{
                GPOName    = $gpo.DisplayName
                GUID       = $gpo.Id
                Path       = $gpoPath
                Identity   = $ace.IdentityReference.Value
                Rights     = $ace.FileSystemRights.ToString()
                AccessType = $ace.AccessControlType.ToString()
                Inherited  = $ace.IsInherited
            }
        }
    }
}

if ($report) {
    Write-Warning "Unexpected SYSVOL write permissions detected: $($report.Count) entries"
    $report | Format-Table -AutoSize
    $report | Export-Csv "C:\Temp\SYSVOL-ACL-Issues-$(Get-Date -Format 'yyyyMMdd').csv" -NoTypeInformation
} else {
    Write-Host "SYSVOL permissions are clean — no unexpected write access found."
}
